using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;
using P1bStudy.Framework;
using Galilego.Core;

// Test560 output: every executed point (including losers and failures), one
// decision row per method/target, and a decision table generated by reading that
// CSV back. No number in the Markdown is typed by hand.
internal static partial class P1bTests
{
    private sealed class DecisionMatrixRow
    {
        public string Scenario = "";
        public string Regime = "";
        public string Method = "";
        public string MethodClass = "";
        public double Target;
        public string TargetKind = "";
        public string Control = "";
        public string ControlKind = "";
        public double ErrMaxM = double.NaN;
        public double ErrFinalM = double.NaN;
        public double ErrMaxV = double.NaN;
        public double CostRhs = double.NaN;
        public double CostLocalFrame = double.NaN;
        public double CostMs = double.NaN;
        public double MsMedian = double.NaN;
        public double MsSpreadPct = double.NaN;
        public long GcBytes;
        public long Steps;
        public long Accepted;
        public long Rejected;
        public long Chunks;
        public long RawRhs;
        public long AuxOps;
        public double FloorM = double.NaN;
        public double FloorV = double.NaN;
        public double TargetOverFloor = double.NaN;
        public string Status = "";
        public string Confidence = "";
        public string Note = "";
        public string ReferenceMethod = "";
        public string ReferenceResolution = "";
        public double EventTargetS = double.NaN;
        public double EventErrS = double.NaN;
        public double EventFloorS = double.NaN;
        public string EventStatus = "";
    }

    private static string DecisionCsvField(string value)
    {
        if (value == null)
        {
            return "";
        }

        if (value.IndexOfAny(new[] { ',', '"', '\n', '\r' }) < 0)
        {
            return value;
        }

        return "\"" + value.Replace("\"", "\"\"") + "\"";
    }

    private static string DecisionCsvNumber(double value)
    {
        return double.IsNaN(value) || double.IsInfinity(value)
            ? ""
            : value.ToString("R", CultureInfo.InvariantCulture);
    }

    private static string DecisionCsvLong(long value)
    {
        return value.ToString(CultureInfo.InvariantCulture);
    }

    private static string DecisionFormatTarget(double value, string kind)
    {
        if (kind == "velocity")
        {
            return value.ToString("G6", CultureInfo.InvariantCulture) + " m/s";
        }

        if (value >= 1000d)
        {
            return (value / 1000d).ToString("G6", CultureInfo.InvariantCulture) + " km";
        }

        return value.ToString("G6", CultureInfo.InvariantCulture) + " m";
    }

    private static void DecisionWriteRunsCsv(
        string path, List<DecisionMethodResult> results)
    {
        var sb = new StringBuilder();
        sb.AppendLine("scenario,regime,method,method_class,control,control_kind,status,"
            + "err_max_m,err_final_m,err_max_v,cost_rhs,cost_local_frame,cost_ms,"
            + "gc_bytes,steps,accepted,rejected,chunks,raw_rhs,aux_ops,note");
        foreach (DecisionMethodResult mr in results)
        {
            foreach (DecisionRun r in mr.Runs)
            {
                sb.Append(DecisionCsvField(mr.Scenario.Label)).Append(',')
                    .Append(DecisionCsvField(mr.Scenario.Regime)).Append(',')
                    .Append(DecisionCsvField(mr.Method.Name)).Append(',')
                    .Append(DecisionCsvField(mr.Method.Class)).Append(',')
                    .Append(DecisionCsvNumber(r.Control)).Append(',')
                    .Append(DecisionCsvField(r.ControlKind)).Append(',')
                    .Append(DecisionCsvField(r.Status)).Append(',')
                    .Append(DecisionCsvNumber(r.ErrMaxM)).Append(',')
                    .Append(DecisionCsvNumber(r.ErrFinalM)).Append(',')
                    .Append(DecisionCsvNumber(r.ErrMaxV)).Append(',')
                    .Append(DecisionCsvNumber(r.CostRhs)).Append(',')
                    .Append(DecisionCsvNumber(r.CostLocalFrame)).Append(',')
                    .Append(DecisionCsvNumber(r.Ms)).Append(',')
                    .Append(DecisionCsvLong(r.GcBytes)).Append(',')
                    .Append(DecisionCsvLong(r.Steps)).Append(',')
                    .Append(DecisionCsvLong(r.Accepted)).Append(',')
                    .Append(DecisionCsvLong(r.Rejected)).Append(',')
                    .Append(DecisionCsvLong(r.Chunks)).Append(',')
                    .Append(DecisionCsvLong(r.RawCalls)).Append(',')
                    .Append(DecisionCsvLong(r.Aux)).Append(',')
                    .Append(DecisionCsvField(r.Note)).AppendLine();
            }
        }

        File.WriteAllText(path, sb.ToString());
    }

    private static void DecisionWriteMatrixCsv(
        string path, List<DecisionMethodResult> results,
        Dictionary<string, DecisionEventResult> events,
        Dictionary<string, double> eventFloors)
    {
        var sb = new StringBuilder();
        sb.AppendLine("scenario,regime,method,method_class,target,target_kind,control,control_kind,"
            + "err_max_m,err_final_m,err_max_v,cost_rhs,cost_local_frame,cost_ms,ms_median,ms_spread_pct,"
            + "gc_bytes,gc_bytes_per_step,gc_bytes_per_chunk,cost_rhs_per_sim_second,cost_rhs_per_chunk,"
            + "steps,accepted,rejected,chunks,raw_rhs,aux_ops,floor_m,floor_v,target_over_floor,"
            + "status,confidence,note,reference_method,reference_resolution,"
            + "event_target_s,event_err_s,event_floor_s,event_status,horizon_seconds,chunk_seconds");

        foreach (DecisionMethodResult mr in results)
        {
            DecisionScenario s = mr.Scenario;
            foreach (DecisionTarget target in s.Targets)
            {
                var row = new DecisionMatrixRow
                {
                    Scenario = s.Label,
                    Regime = s.Regime,
                    Method = mr.Method.Name,
                    MethodClass = mr.Method.Class,
                    Target = target.Value,
                    TargetKind = target.Kind,
                    FloorM = s.FloorM,
                    FloorV = s.FloorV,
                    ReferenceMethod = s.Refs.LocalKind ?? "",
                    ReferenceResolution = s.Refs.LocalAsymptotic ? "ratio_ok"
                        : (s.Refs.LocalResolved ? "resolved_finest_delta" : "not_certified")
                };

                double floor = target.Kind == "velocity" ? s.FloorV : s.FloorM;
                row.TargetOverFloor = double.IsFinite(floor) && floor > 0d
                    ? target.Value / floor
                    : double.NaN;

                if (mr.Status == "unsupported")
                {
                    row.Status = "n/a";
                    row.Confidence = "n/a";
                    row.Note = mr.UnsupportedReason;
                }
                else if (!double.IsFinite(floor))
                {
                    row.Status = "skip";
                    row.Confidence = "low";
                    row.Note = "reference floor is not certified for this quantity";
                }
                else if (target.Value < 10d * floor)
                {
                    row.Status = "skip";
                    row.Confidence = "low";
                    row.Note = "target " + DecisionFormatTarget(target.Value, target.Kind)
                        + " < 10 x reference floor " + floor.ToString("E3", CultureInfo.InvariantCulture);
                }
                else
                {
                    DecisionRun hit = DecisionCheapestHit(mr.Runs, target.Value, target.Kind);
                    if (hit != null)
                    {
                        row.Status = "ok";
                        double cellErr = target.Kind == "velocity" ? hit.ErrMaxV : hit.ErrMaxM;
                        row.Confidence = cellErr <= 0.5d * target.Value ? "high" : "medium";
                        row.Control = hit.Control.ToString("R", CultureInfo.InvariantCulture);
                        row.ControlKind = hit.ControlKind;
                        row.ErrMaxM = hit.ErrMaxM;
                        row.ErrFinalM = hit.ErrFinalM;
                        row.ErrMaxV = hit.ErrMaxV;
                        row.CostRhs = hit.CostRhs;
                        row.CostLocalFrame = hit.CostLocalFrame;
                        row.CostMs = hit.Ms;
                        row.MsMedian = hit.MsMedian;
                        row.MsSpreadPct = hit.MsSpreadPct;
                        row.GcBytes = hit.GcBytes;
                        row.Steps = hit.Steps;
                        row.Accepted = hit.Accepted;
                        row.Rejected = hit.Rejected;
                        row.Chunks = hit.Chunks;
                        row.RawRhs = hit.RawCalls;
                        row.AuxOps = hit.Aux;
                        row.Note = hit.Note;
                    }
                    else
                    {
                        DecisionRun best = null;
                        foreach (DecisionRun r in mr.Runs)
                        {
                            if (r.Status != "ok" || !r.Finite)
                            {
                                continue;
                            }

                            if (best == null || r.ErrMaxM < best.ErrMaxM)
                            {
                                best = r;
                            }
                        }

                        row.Status = "no_hit";
                        row.Confidence = "low";
                        if (best != null)
                        {
                            row.Control = best.Control.ToString("R", CultureInfo.InvariantCulture);
                            row.ControlKind = best.ControlKind;
                            row.ErrMaxM = best.ErrMaxM;
                            row.ErrFinalM = best.ErrFinalM;
                            row.ErrMaxV = best.ErrMaxV;
                            row.CostRhs = best.CostRhs;
                            row.CostLocalFrame = best.CostLocalFrame;
                            row.CostMs = best.Ms;
                            row.GcBytes = best.GcBytes;
                            row.Steps = best.Steps;
                            row.Accepted = best.Accepted;
                            row.Rejected = best.Rejected;
                            row.Chunks = best.Chunks;
                            row.RawRhs = best.RawCalls;
                            row.AuxOps = best.Aux;
                            row.Note = "finest executed run: " + best.ErrMaxM.ToString("E3", CultureInfo.InvariantCulture);
                        }
                        else
                        {
                            row.Note = "no finite executed run";
                        }

                        if (s.Label.IndexOf("5 AU", StringComparison.Ordinal) >= 0 && mr.Method.Production)
                        {
                            row.Note = (row.Note + "; production local-frame path misses the target at all tested tolerances; "
                                + "see the production_dominant_body finding (Jupiter-crossing arc)").Trim();
                        }
                    }
                }

                string eventKey = s.Label + "|" + mr.Method.Name;
                DecisionEventResult ev;
                if (events.TryGetValue(eventKey, out ev))
                {
                    row.EventTargetS = s.EventTargetSeconds;
                    row.EventErrS = ev.Time;
                    row.EventStatus = ev.Status;
                    double evFloor;
                    if (eventFloors.TryGetValue(s.Label, out evFloor))
                    {
                        row.EventFloorS = evFloor;
                        if (ev.Status == "ok" && double.IsFinite(ev.Time))
                        {
                            double refTime = eventFloors[s.Label + "|ref"];
                            row.EventErrS = Math.Abs(ev.Time - refTime);
                        }
                    }

                    if (!string.IsNullOrEmpty(ev.Note))
                    {
                        row.Note = (row.Note.Length == 0 ? "" : row.Note + "; ") + ev.Note;
                    }
                }

                sb.Append(DecisionCsvField(row.Scenario)).Append(',')
                    .Append(DecisionCsvField(row.Regime)).Append(',')
                    .Append(DecisionCsvField(row.Method)).Append(',')
                    .Append(DecisionCsvField(row.MethodClass)).Append(',')
                    .Append(DecisionCsvNumber(row.Target)).Append(',')
                    .Append(DecisionCsvField(row.TargetKind)).Append(',')
                    .Append(DecisionCsvField(row.Control)).Append(',')
                    .Append(DecisionCsvField(row.ControlKind)).Append(',')
                    .Append(DecisionCsvNumber(row.ErrMaxM)).Append(',')
                    .Append(DecisionCsvNumber(row.ErrFinalM)).Append(',')
                    .Append(DecisionCsvNumber(row.ErrMaxV)).Append(',')
                    .Append(DecisionCsvNumber(row.CostRhs)).Append(',')
                    .Append(DecisionCsvNumber(row.CostLocalFrame)).Append(',')
                    .Append(DecisionCsvNumber(row.CostMs)).Append(',')
                    .Append(DecisionCsvNumber(row.MsMedian)).Append(',')
                    .Append(DecisionCsvNumber(row.MsSpreadPct)).Append(',')
                    .Append(DecisionCsvLong(row.GcBytes)).Append(',')
                    .Append(DecisionCsvNumber(row.Steps > 0 ? (double)row.GcBytes / row.Steps : double.NaN)).Append(',')
                    .Append(DecisionCsvNumber(row.Chunks > 0 ? (double)row.GcBytes / row.Chunks : double.NaN)).Append(',')
                    .Append(DecisionCsvNumber(s.Case.Seconds > 0d ? row.CostRhs / s.Case.Seconds : double.NaN)).Append(',')
                    .Append(DecisionCsvNumber(row.Chunks > 0 ? row.CostRhs / row.Chunks : double.NaN)).Append(',')
                    .Append(DecisionCsvLong(row.Steps)).Append(',')
                    .Append(DecisionCsvLong(row.Accepted)).Append(',')
                    .Append(DecisionCsvLong(row.Rejected)).Append(',')
                    .Append(DecisionCsvLong(row.Chunks)).Append(',')
                    .Append(DecisionCsvLong(row.RawRhs)).Append(',')
                    .Append(DecisionCsvLong(row.AuxOps)).Append(',')
                    .Append(DecisionCsvNumber(row.FloorM)).Append(',')
                    .Append(DecisionCsvNumber(row.FloorV)).Append(',')
                    .Append(DecisionCsvNumber(row.TargetOverFloor)).Append(',')
                    .Append(DecisionCsvField(row.Status)).Append(',')
                    .Append(DecisionCsvField(row.Confidence)).Append(',')
                    .Append(DecisionCsvField(row.Note)).Append(',')
                    .Append(DecisionCsvField(row.ReferenceMethod)).Append(',')
                    .Append(DecisionCsvField(row.ReferenceResolution)).Append(',')
                    .Append(DecisionCsvNumber(row.EventTargetS)).Append(',')
                    .Append(DecisionCsvNumber(row.EventErrS)).Append(',')
                    .Append(DecisionCsvNumber(row.EventFloorS)).Append(',')
                    .Append(DecisionCsvField(row.EventStatus)).Append(',')
                    .Append(DecisionCsvNumber(s.Case.Seconds)).Append(',')
                    .Append(DecisionCsvNumber(s.ChunkSeconds)).AppendLine();
            }
        }

        File.WriteAllText(path, sb.ToString());
    }

