    private static void DecisionWriteWarpCsv(string path, List<DecisionWarpRow> rows)
    {
        var sb = new StringBuilder();
        sb.AppendLine("scenario,regime,method,factor,sim_seconds,chunks,calls,cost_rhs,cost_local_frame,"
            + "ms,ms_per_real_second,gc_bytes,status,note");
        foreach (DecisionWarpRow r in rows)
        {
            // Ms is already the wall-clock cost of one real second (60 frames).
            // SimSeconds is the simulated span advanced in that real second.
            double perSecond = r.Ms;
            sb.Append(DecisionCsvField(r.Scenario)).Append(',')
                .Append(DecisionCsvField(r.Regime)).Append(',')
                .Append(DecisionCsvField(r.Method)).Append(',')
                .Append(DecisionCsvNumber(r.Factor)).Append(',')
                .Append(DecisionCsvNumber(r.SimSeconds)).Append(',')
                .Append(DecisionCsvLong(r.Chunks)).Append(',')
                .Append(DecisionCsvLong(r.Calls)).Append(',')
                .Append(DecisionCsvNumber(r.CostRhs)).Append(',')
                .Append(DecisionCsvNumber(r.CostLocalFrame)).Append(',')
                .Append(DecisionCsvNumber(r.Ms)).Append(',')
                .Append(DecisionCsvNumber(perSecond)).Append(',')
                .Append(DecisionCsvLong(r.GcBytes)).Append(',')
                .Append(DecisionCsvField(r.Status)).Append(',')
                .Append(DecisionCsvField(r.Note)).AppendLine();
        }

        File.WriteAllText(path, sb.ToString());
    }

