    private sealed class DecisionEventRow
    {
        public string Scenario;
        public string Regime;
        public string Method;
        public double Control;
        public string Kind;
        public double TargetSeconds;
        public double TimeSeconds;
        public double ErrorSeconds;
        public double FloorSeconds;
        public double CostRhs;
        public string Status;
        public string Note;
    }

    // ------------------------------------------------------------------------------------
    // CSV reader and decision-table generator
    // ------------------------------------------------------------------------------------

    private static List<string> DecisionCsvSplit(string line)
    {
        var fields = new List<string>();
        var sb = new StringBuilder();
        bool quoted = false;
        for (int i = 0; i < line.Length; i++)
        {
            char c = line[i];
            if (quoted)
            {
                if (c == '"')
                {
                    if (i + 1 < line.Length && line[i + 1] == '"')
                    {
                        sb.Append('"');
                        i++;
                    }
                    else
                    {
                        quoted = false;
                    }
                }
                else
                {
                    sb.Append(c);
                }
            }
            else if (c == '"')
            {
                quoted = true;
            }
            else if (c == ',')
            {
                fields.Add(sb.ToString());
                sb.Length = 0;
            }
            else
            {
                sb.Append(c);
            }
        }

        fields.Add(sb.ToString());
        return fields;
    }

    private static double DecisionParseDouble(string s)
    {
        double v;
        return double.TryParse(s, NumberStyles.Float, CultureInfo.InvariantCulture, out v)
            ? v
            : double.NaN;
    }

    private sealed class DecisionTableRow
    {
        public string Regime = "";
        public string Scenario = "";
        public double Target;
        public string TargetKind = "";
        public string Recommended = "";
        public string Acceptable = "";
        public string Na = "";
        public string Confidence = "";
        public string Why = "";
        public List<string> Unresolved = new List<string>();
    }

    private static List<DecisionTableRow> DecisionReadTable(string csvPath)
    {
        var rows = new List<DecisionTableRow>();
        if (!File.Exists(csvPath))
        {
            return rows;
        }

        string[] lines = File.ReadAllLines(csvPath);
        if (lines.Length < 2)
        {
            return rows;
        }

        List<string> header = DecisionCsvSplit(lines[0]);
        var index = new Dictionary<string, int>(StringComparer.Ordinal);
        for (int i = 0; i < header.Count; i++)
        {
            index[header[i]] = i;
        }

        var groups = new Dictionary<string, List<Dictionary<string, string>>>(StringComparer.Ordinal);
        for (int i = 1; i < lines.Length; i++)
        {
            if (string.IsNullOrWhiteSpace(lines[i]))
            {
                continue;
            }

            List<string> f = DecisionCsvSplit(lines[i]);
            var row = new Dictionary<string, string>(StringComparer.Ordinal);
            foreach (var kv in index)
            {
                if (kv.Value < f.Count)
                {
                    row[kv.Key] = f[kv.Value];
                }
            }

            string key = row["scenario"] + "|" + row["target"] + "|" + row["target_kind"];
            List<Dictionary<string, string>> list;
            if (!groups.TryGetValue(key, out list))
            {
                list = new List<Dictionary<string, string>>();
                groups[key] = list;
            }

            list.Add(row);
        }

        foreach (var group in groups)
        {
            List<Dictionary<string, string>> list = group.Value;
            var ok = new List<Dictionary<string, string>>();
            var na = new List<string>();
            var unresolved = new List<string>();
            foreach (Dictionary<string, string> r in list)
            {
                string status = r["status"];
                if (status == "ok")
                {
                    ok.Add(r);
                }
                else if (status == "n/a")
                {
                    na.Add(r["method"]);
                }
                else
                {
                    unresolved.Add(r["method"] + ":" + status);
                }
            }

            ok.Sort(delegate (Dictionary<string, string> a, Dictionary<string, string> b)
            {
                return DecisionParseDouble(a["cost_rhs"]).CompareTo(DecisionParseDouble(b["cost_rhs"]));
            });

            var table = new DecisionTableRow();
            table.Regime = list[0]["regime"];
            table.Scenario = list[0]["scenario"];
            table.Target = DecisionParseDouble(list[0]["target"]);
            table.TargetKind = list[0]["target_kind"];
            table.Na = na.Count == 0 ? "—" : string.Join(", ", na);

            if (ok.Count == 0)
            {
                table.Recommended = "unresolved";
                table.Acceptable = "—";
                table.Confidence = "low";
                table.Why = "no executed method reached " + DecisionFormatTarget(table.Target, table.TargetKind)
                    + "; see failed/unresolved list";
                table.Unresolved = unresolved;
                rows.Add(table);
                continue;
            }

            double best = DecisionParseDouble(ok[0]["cost_rhs"]);
            double tieBand = 1.20d;
            var ties = new List<string>();
            foreach (Dictionary<string, string> r in ok)
            {
                double cost = DecisionParseDouble(r["cost_rhs"]);
                if (cost <= best * tieBand)
                {
                    ties.Add(r["method"]);
                }
            }

            table.Recommended = ties.Count == 1
                ? ties[0]
                : "tie: " + string.Join(", ", ties);

            var acceptable = new List<string>();
            foreach (Dictionary<string, string> r in ok)
            {
                if (ties.Contains(r["method"]))
                {
                    continue;
                }

                double cost = DecisionParseDouble(r["cost_rhs"]);
                acceptable.Add(r["method"] + " (+"
                    + (100d * (cost / Math.Max(best, 1e-30d) - 1d)).ToString("F0", CultureInfo.InvariantCulture)
                    + "%)");
            }

            table.Acceptable = acceptable.Count == 0 ? "—" : string.Join(", ", acceptable);
            table.Unresolved = unresolved;

            double floor = DecisionParseDouble(ok[0]["floor_m"]);
            if (table.TargetKind == "velocity")
            {
                floor = DecisionParseDouble(ok[0]["floor_v"]);
            }

            double margin = ok.Count > 1
                ? DecisionParseDouble(ok[1]["cost_rhs"]) / Math.Max(best, 1e-30d) - 1d
                : double.PositiveInfinity;
            bool bestProduction = ok[0]["method_class"] == "production";
            bool floorHigh = double.IsFinite(floor) && floor <= table.Target / 100d;
            bool floorOk = double.IsFinite(floor) && floor <= table.Target / 10d;

            if (ties.Count > 1)
            {
                table.Confidence = "low";
            }
            else if (!floorOk)
            {
                table.Confidence = "low";
            }
            else if (bestProduction && margin >= 0.20d && floorHigh)
            {
                table.Confidence = "high";
            }
            else if (margin >= 0.20d)
            {
                table.Confidence = "medium";
            }
            else
            {
                table.Confidence = "low";
            }

            string bestMethod = ok[0]["method"];
            string bestClass = ok[0]["method_class"];
            string second = ok.Count > 1 ? ok[1]["method"] : "—";
            string secondCost = ok.Count > 1 ? ok[1]["cost_rhs"] : "—";
            double bestErr = table.TargetKind == "velocity"
                ? DecisionParseDouble(ok[0]["err_max_v"])
                : DecisionParseDouble(ok[0]["err_max_m"]);
            double errFraction = double.IsFinite(bestErr) ? bestErr / table.Target : double.NaN;

            // A hit at 80-100% of the accuracy budget is not the same answer as a
            // hit with a 1e-4 margin. Downgrade one confidence level.
            if (double.IsFinite(errFraction) && errFraction > 0.8d)
            {
                if (table.Confidence == "high")
                {
                    table.Confidence = "medium";
                }
                else if (table.Confidence == "medium")
                {
                    table.Confidence = "low";
                }
            }

            table.Why = bestMethod + " is cheapest executed hit at "
                + DecisionParseDouble(ok[0]["cost_rhs"]).ToString("N0", CultureInfo.InvariantCulture)
                + " RHS (" + bestClass + ", control " + ok[0]["control_kind"] + "=" + ok[0]["control"] + "); "
                + "next " + second + " " + secondCost + " RHS; "
                + "err/target " + (double.IsFinite(errFraction) ? errFraction.ToString("G3", CultureInfo.InvariantCulture) : "NaN")
                + "; floor " + (double.IsFinite(floor) ? floor.ToString("E2", CultureInfo.InvariantCulture) : "NaN")
                + " m; tie band 20%; "
                + ok.Count + " hit, " + na.Count + " n/a, " + unresolved.Count + " unresolved";
            rows.Add(table);
        }

        rows.Sort(delegate (DecisionTableRow a, DecisionTableRow b)
        {
            int c = string.CompareOrdinal(a.Regime, b.Regime);
            if (c != 0)
            {
                return c;
            }

            c = string.CompareOrdinal(a.Scenario, b.Scenario);
            if (c != 0)
            {
                return c;
            }

            return a.Target.CompareTo(b.Target);
        });
        return rows;
    }

    private static void DecisionWriteDecisionCsv(string path, List<DecisionTableRow> rows)
    {
        var sb = new StringBuilder();
        sb.AppendLine("regime,scenario,target,target_kind,recommended,acceptable,n_a,confidence,why");
        foreach (DecisionTableRow r in rows)
        {
            sb.Append(DecisionCsvField(r.Regime)).Append(',')
                .Append(DecisionCsvField(r.Scenario)).Append(',')
                .Append(DecisionCsvNumber(r.Target)).Append(',')
                .Append(DecisionCsvField(r.TargetKind)).Append(',')
                .Append(DecisionCsvField(r.Recommended)).Append(',')
                .Append(DecisionCsvField(r.Acceptable)).Append(',')
                .Append(DecisionCsvField(r.Na)).Append(',')
                .Append(DecisionCsvField(r.Confidence)).Append(',')
                .Append(DecisionCsvField(r.Why)).AppendLine();
        }

        File.WriteAllText(path, sb.ToString());
    }

    private static void DecisionWriteMarkdown(
        string path, string matrixCsv, string decisionCsv,
        string validityCsv, string eventCsv, string warpCsv)
    {
        List<DecisionTableRow> table = DecisionReadTable(matrixCsv);
        var header = new List<string>();
        var rows = new List<List<string>>();
        if (File.Exists(matrixCsv))
        {
            string[] lines = File.ReadAllLines(matrixCsv);
            if (lines.Length > 0)
            {
                header = DecisionCsvSplit(lines[0]);
            }

            for (int i = 1; i < lines.Length; i++)
            {
                if (!string.IsNullOrWhiteSpace(lines[i]))
                {
                    rows.Add(DecisionCsvSplit(lines[i]));
                }
            }
        }

        Func<string, int> col = name =>
        {
            int idx = header.IndexOf(name);
            return idx < 0 ? 0 : idx;
        };

        var scenarioOrder = new List<string>();
        var scenarioInfo = new Dictionary<string, string[]>(StringComparer.Ordinal);
        var scenarioTargets = new Dictionary<string, List<string>>(StringComparer.Ordinal);
        foreach (List<string> row in rows)
        {
            string label = row[col("scenario")];
            if (!scenarioInfo.ContainsKey(label))
            {
                scenarioOrder.Add(label);
                scenarioInfo[label] = new[]
                {
                    row[col("regime")],
                    row[col("horizon_seconds")],
                    row[col("chunk_seconds")],
                    row[col("floor_m")],
                    (row[col("reference_method")] ?? "") + " [" + (row[col("reference_resolution")] ?? "") + "]"
                };
                scenarioTargets[label] = new List<string>();
            }

            string target = DecisionFormatTarget(
                DecisionParseDouble(row[col("target")]), row[col("target_kind")]);
            if (!scenarioTargets[label].Contains(target))
            {
                scenarioTargets[label].Add(target);
            }
        }

        var sb = new StringBuilder();
        sb.AppendLine("# Test560 — integrator decision matrix");
        sb.AppendLine();
        sb.AppendLine("Generated from `" + Path.GetFileName(matrixCsv) + "` by Test560 on "
            + DateTime.UtcNow.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture) + " UTC.");
        sb.AppendLine("Every cost/error cell below is the cheapest **executed** run from `"
            + Path.GetFileName(matrixCsv) + "`; all executed points, including losers and failures, are in "
            + "`Test560_Runs.csv`. No cost is interpolated.");
        sb.AppendLine();

        sb.AppendLine("## Audit of the existing stand (Test551-Test559)");
        sb.AppendLine();
        sb.AppendLine("- Covered before Test560: Test551 framework self-test; Test552 spacecraft sweep (LEO,");
        sb.AppendLine("  GTO/HEO, J2, drag, thrust, Moon flyby); Test553 planet sweep; Test554 orbit edge cases");
        sb.AppendLine("  (Moon/SOI, hyperbolic, 30 d, 1000 orbits); Test555 low-altitude/landing (archived);");
        sb.AppendLine("  Test557 production chunking (archived); Test558 J2/inclination and normalized Sun;");
        sb.AppendLine("  Test559 pure gravity (Moon, heliocentric, flybys). The post-audit results are in");
        sb.AppendLine("  `integrators/results/`; `results_baseline/` and the numbers in");
        sb.AppendLine("  `ORBIT_INTEGRATOR_TEST_SCHEME.md` are historical and are not used here.");
        sb.AppendLine("- Methods already in `StudyRegistry`: DOP853, DOPRI5 (also the two production");
        sb.AppendLine("  integrators), plus stand-only RK4, PEFRL, Y6/Y6C, WH-Y6, leapfrog, RKN12(10),");
        sb.AppendLine("  IAS15, SRKN14A, WH-BM14A, GJ8, Encke-IAS15. Test560 uses only DOP853/DOPRI5 from");
        sb.AppendLine("  production and WH-BM14A/RKN12(10)/IAS15 from the stand; no new mathematics is added.");
        sb.AppendLine("- Valid before Test560: reference certification/floors, the single executed-hit cost rule");
        sb.AppendLine("  (`calls + w*aux`, no interpolation), rejected/step accounting, and the T1-T9 audit.");
        sb.AppendLine("- Gaps Test560 fills: one decision table per regime; the real `SpacecraftPhysics` path with");
        sb.AppendLine("  game chunks and tolerances; 3D surface with drag/thrust/variable mass; high orbit");
        sb.AppendLine("  20 000-400 000 km; cislunar SOI entry/exit; heliocentric 1 y/10 y; far flight 30 AU/10 y;");
        sb.AppendLine("  touchdown/SOI event time; production parity, determinism and chunk invariance in one place.");
        sb.AppendLine();
        sb.AppendLine("## Method");
        sb.AppendLine();
        sb.AppendLine("- Force model: the production local-frame field `StarSystem.EvaluateShipAccelerationLocal`");
        sb.AppendLine("  (central body + J2 + every other body's direct-minus-indirect term), plus the real");
        sb.AppendLine("  `DragSource` and `ThrustSource` where the regime requires them.");
        sb.AppendLine("- Reference: certified fixed-step DOP853 in the same local frame, five step levels,");
        sb.AppendLine("  Richardson ratio and round-off floor (`CertifiedReference.cs`). When the five levels");
        sb.AppendLine("  have no asymptotic Richardson pair (baked-ephemeris seams, drag/thrust corners), the");
        sb.AppendLine("  finest observed level disagreement is used as the bound and accepted only when it is");
        sb.AppendLine("  <= target/100 (`resolved_finest_delta` in the CSV); this is a weaker certificate than");
        sb.AppendLine("  `ratio_ok` and is labelled as such. The floor is printed per scenario and a target");
        sb.AppendLine("  below 10 x floor is marked `skip`.");
        sb.AppendLine("- Candidates: production `SpacecraftPhysics` (DOP853, DOPRI5) through the real");
        sb.AppendLine("  `VesselStep`-style chunking; stand-only `WH-BM14A`, `RKN12(10)`, `IAS15` through the");
        sb.AppendLine("  existing `StudyRegistry`, restarted at every chunk boundary like a ported method would be.");
        sb.AppendLine("  Both candidate paths stop at the same measurement checkpoints; the extra controller");
        sb.AppendLine("  restart is included in the cost. Burn start/stop and ramp corners are force breakpoints");
        sb.AppendLine("  and are landed on exactly (so their event-time error is zero by construction, not");
        sb.AppendLine("  ranked); touchdown and SOI exit are found by dense output (production) or local root");
        sb.AppendLine("  finding (stand) and are reported in `Test560_Events.csv`.");
        sb.AppendLine("- Cost unit: one RHS/force evaluation. For production, `cost_local_frame` additionally");
        sb.AppendLine("  reports the three gravity sums per local derivative plus one torque-snapshot call per chunk.");
        sb.AppendLine("  WH-BM14A also pays its Kepler solves at the measured per-scenario weight `w`; the");
        sb.AppendLine("  measurement and its CV are in `Test560_kepler_weights.csv` (CV 3-32%). WH is never");
        sb.AppendLine("  the winner, so that uncertainty does not change a recommendation.");
        sb.AppendLine("- Tie rule: a cost difference below 20% is written as `tie`, not as a winner.");
        sb.AppendLine("- Confidence: high = production winner, margin >= 20%, floor <= target/100; medium =");
        sb.AppendLine("  margin >= 20% but stand-only or floor <= target/10; low = tie, no hit, or floor-limited.");
        sb.AppendLine();

        sb.AppendLine("## Scenarios");
        sb.AppendLine();
        sb.AppendLine("| scenario | regime | horizon | chunk | targets | floor (m) | reference |");
        sb.AppendLine("|---|---|---:|---:|---|---:|---|");
        foreach (string label in scenarioOrder)
        {
            string[] info = scenarioInfo[label];
            string targets = string.Join(", ", scenarioTargets[label]);
            sb.Append("| ").Append(DecisionCsvField(label)).Append(" | ")
                .Append(info[0]).Append(" | ")
                .Append(info[1]).Append(" s | ")
                .Append(info[2]).Append(" s | ")
                .Append(targets).Append(" | ")
                .Append(info[3]).Append(" | ")
                .Append(info[4]).AppendLine(" |");
        }

        sb.AppendLine();
        sb.AppendLine("## Per-regime cells");
        sb.AppendLine();
        foreach (DecisionTableRow r in table)
        {
            sb.AppendLine("### " + r.Scenario + " / " + DecisionFormatTarget(r.Target, r.TargetKind));
            sb.AppendLine();
            sb.AppendLine("| method | target | control | err max | cost RHS | cost local frame | RHS/sim s | GC B/step | ms | status | confidence |");
            sb.AppendLine("|---|---:|---|---:|---:|---:|---:|---:|---:|---|---|");
            foreach (List<string> f in rows)
            {
                if (f.Count < 34)
                {
                    continue;
                }

                if (f[0] != r.Scenario || Math.Abs(DecisionParseDouble(f[4]) - r.Target) > 1e-12d
                    || f[5] != r.TargetKind)
                {
                    continue;
                }

                double err = DecisionParseDouble(f[8]);
                double cost = DecisionParseDouble(f[11]);
                double local = DecisionParseDouble(f[12]);
                double ms = DecisionParseDouble(f[13]);
                double perSim = DecisionParseDouble(f[19]);
                double gcStep = DecisionParseDouble(f[17]);
                sb.Append("| ").Append(f[2]).Append(" | ")
                    .Append(DecisionFormatTarget(DecisionParseDouble(f[4]), f[5])).Append(" | ")
                    .Append(f[7]).Append("=").Append(f[6]).Append(" | ")
                    .Append(double.IsFinite(err) ? err.ToString("E3", CultureInfo.InvariantCulture) : "—").Append(" | ")
                    .Append(double.IsFinite(cost) ? cost.ToString("N0", CultureInfo.InvariantCulture) : "—").Append(" | ")
                    .Append(double.IsFinite(local) ? local.ToString("N0", CultureInfo.InvariantCulture) : "—").Append(" | ")
                    .Append(double.IsFinite(perSim) ? perSim.ToString("E2", CultureInfo.InvariantCulture) : "—").Append(" | ")
                    .Append(double.IsFinite(gcStep) ? gcStep.ToString("F0", CultureInfo.InvariantCulture) : "—").Append(" | ")
                    .Append(double.IsFinite(ms) ? ms.ToString("F1", CultureInfo.InvariantCulture) : "—").Append(" | ")
                    .Append(f[30]).Append(" | ").Append(f[31]).AppendLine(" |");
            }

            sb.AppendLine();
        }

        sb.AppendLine("## Decision table");
        sb.AppendLine();
        sb.AppendLine("| regime | scenario | target | recommended | acceptable | n/a | confidence | why |");
        sb.AppendLine("|---|---|---|---|---|---|---|---|");
        foreach (DecisionTableRow r in table)
        {
            sb.Append("| ").Append(r.Regime).Append(" | ")
                .Append(DecisionCsvField(r.Scenario)).Append(" | ")
                .Append(DecisionFormatTarget(r.Target, r.TargetKind)).Append(" | ")
                .Append(r.Recommended).Append(" | ")
                .Append(r.Acceptable).Append(" | ")
                .Append(r.Na).Append(" | ")
                .Append(r.Confidence).Append(" | ")
                .Append(r.Why).AppendLine(" |");
        }

        sb.AppendLine();
        sb.AppendLine("## Warp cost (real 60-frame runs)");
        sb.AppendLine();
        sb.AppendLine("Each cell is the measured RHS cost of one real second at that warp factor, integrated");
        sb.AppendLine("with the scenario's chunk size. At 1000x this is 60 frames x 16.67 s of simulated time.");
        sb.AppendLine("This is the direct `SpacecraftPhysics` path; actual long warp in the game uses");
        sb.AppendLine("`LongWarpDriver`, which is not compared here. Rows with a 600 s or 86 400 s chunk are");
        sb.AppendLine("frame-rate-bound at these factors (one step per frame, 60 frames/s); the surface rows");
        sb.AppendLine("with a 0.5/0.05 s chunk show the expected growth with warp.");
        sb.AppendLine();
        sb.AppendLine("| scenario | method | 1x RHS/s | 10x | 100x | 1000x |");
        sb.AppendLine("|---|---|---:|---:|---:|---:|");
        if (File.Exists(warpCsv))
        {
            var warp = new Dictionary<string, Dictionary<double, double>>(StringComparer.Ordinal);
            var labels = new Dictionary<string, string>(StringComparer.Ordinal);
            foreach (string line in File.ReadLines(warpCsv))
            {
                if (line.StartsWith("scenario,", StringComparison.Ordinal) || string.IsNullOrWhiteSpace(line))
                {
                    continue;
                }

                List<string> f = DecisionCsvSplit(line);
                if (f.Count < 10)
                {
                    continue;
                }

                string key = f[0] + "|" + f[2];
                labels[key] = "| " + f[0] + " | " + f[2] + " |";
                Dictionary<double, double> factors;
                if (!warp.TryGetValue(key, out factors))
                {
                    factors = new Dictionary<double, double>();
                    warp[key] = factors;
                }

                factors[DecisionParseDouble(f[3])] = DecisionParseDouble(f[7]);
            }

            foreach (var kv in warp)
            {
                sb.Append(labels[kv.Key]);
                foreach (double factor in new[] { 1d, 10d, 100d, 1000d })
                {
                    double cost;
                    sb.Append(' ').Append(kv.Value.TryGetValue(factor, out cost) && double.IsFinite(cost)
                        ? cost.ToString("N0", CultureInfo.InvariantCulture)
                        : "—").Append(" |");
                }

                sb.AppendLine();
            }
        }

        sb.AppendLine();
        sb.AppendLine("## Failed / unresolved");
        sb.AppendLine();
        bool anyUnresolved = false;
        foreach (DecisionTableRow r in table)
        {
            if (r.Unresolved.Count == 0)
            {
                continue;
            }

            anyUnresolved = true;
            sb.AppendLine("- " + r.Regime + " / " + r.Scenario + " / "
                + DecisionFormatTarget(r.Target, r.TargetKind)
                + ": " + string.Join(", ", r.Unresolved));
        }

        if (!anyUnresolved)
        {
            sb.AppendLine("- none");
        }

        sb.AppendLine();
        sb.AppendLine("## Production-available vs stand-only");
        sb.AppendLine();
        sb.AppendLine("- **Production-available:** DOP853, DOPRI5 (selected by `SpacecraftPhysics.Integrator`;");
        sb.AppendLine("  DOP853 remains the default).");
        sb.AppendLine("- **Stand-only, requires porting:** WH-BM14A, RKN12(10), IAS15. Their cells are measurements");
        sb.AppendLine("  of the existing StudyRegistry implementations, not claims about code already in the game.");
        sb.AppendLine("  WH-BM14A/Encke-style methods require one central body at the origin; RKN12(10) and WH-BM14A");
        sb.AppendLine("  are reported `n/a` on drag/thrust scenarios because their splitting/order assumptions do not hold.");
        sb.AppendLine();
        sb.AppendLine("## Validity");
        sb.AppendLine();
        sb.AppendLine("- `" + Path.GetFileName(validityCsv) + "`: production default, determinism, production parity");
        sb.AppendLine("  (SpacecraftPhysics vs stand DOP853 at the same tight tolerance) and chunk invariance.");
        if (File.Exists(validityCsv))
        {
            foreach (string line in File.ReadLines(validityCsv))
            {
                List<string> f = DecisionCsvSplit(line);
                if (f.Count >= 8 && (f[0] == "local_frame_error_control" || f[0] == "production_dominant_body"))
                {
                    sb.AppendLine("  `" + f[0] + "` FINDING: " + f[3] + " = " + f[4]
                        + "; " + f[7]);
                }
            }
        }
        sb.AppendLine("- `" + Path.GetFileName(eventCsv) + "`: touchdown / SOI event time via dense output or root finding.");
        sb.AppendLine("- `" + Path.GetFileName(warpCsv) + "`: real 60-frame runs at 1x/10x/100x/1000x, cost per real second.");
        sb.AppendLine("- `Test560_Runs.csv`: every executed point, including rejected/censored/error runs.");

        File.WriteAllText(path, sb.ToString());
    }
}
